schema_ddl:
CREATE TABLE conti (
    id SERIAL PRIMARY KEY,
    codice_conto TEXT NOT NULL UNIQUE,
    denominazione TEXT NOT NULL,
    natura_conto TEXT NOT NULL CHECK (natura_conto IN ('attivo', 'passivo', 'costo', 'ricavo'))
);

CREATE TABLE registrazioni (
    id SERIAL PRIMARY KEY,
    numero_protocollo INT NOT NULL UNIQUE CHECK (numero_protocollo > 0),
    data_registrazione DATE NOT NULL,
    causale TEXT NOT NULL,
    descrizione_scrittura TEXT
);

CREATE TABLE movimenti (
    id SERIAL PRIMARY KEY,
    registrazione_id INT NOT NULL REFERENCES registrazioni(id),
    conto_id INT NOT NULL REFERENCES conti(id),
    importo NUMERIC(12,2) NOT NULL,
    sezione_dare_avere TEXT NOT NULL CHECK (sezione_dare_avere IN ('dare', 'avere'))
);
